<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router';
import { api, errorText, mutationId, ApiError } from '../api';
import type { JourneySummary, ShareOptions, SharePreview, ShareLink } from '../../../packages/contracts/src/index.js';
import SharedContent from '../components/SharedContent.vue';
import AtlasIcon from '../components/AtlasIcon.vue';
import '../styles/shares.css';
const page = useRoute(), router = useRouter(), journey = ref<JourneySummary | null>(null), choices = ref<{ enabled: boolean; diaries: { id: string; title: string }[] } | null>(null), links = ref<ShareLink[]>([]);
const loading = ref(true), busy = ref(false), error = ref(''), message = ref(''), preview = ref<SharePreview | null>(null), acknowledge = ref(false), lastLink = ref<ShareLink | null>(null);
const options = ref<ShareOptions>({ title: '', layer: page.query.layer === 'actual' ? 'actual' : 'plan', includeDates: false, includeNotes: false, diaryIds: [], includePhotos: false, expiresInDays: 7 });
const photoSources = computed(() => Object.fromEntries(preview.value?.photoPreviews.map(p => [p.key, p.url]) ?? [])); let createKey = mutationId();
watch(() => JSON.stringify(options.value), () => { preview.value = null; acknowledge.value = false; createKey = mutationId(); message.value = ''; });
async function refresh() { links.value = await api('/journeys/' + page.params.id + '/shares'); }
async function load() {
  loading.value = true; error.value = '';
  try { journey.value = await api('/journeys/' + page.params.id); options.value.title = journey.value!.title; choices.value = await api('/journeys/' + page.params.id + '/share-options'); await refresh(); }
  catch (e) { error.value = errorText(e); } finally { loading.value = false; }
}
onMounted(load);
async function showPreview() { busy.value = true; error.value = ''; message.value = ''; acknowledge.value = false; try { preview.value = await api('/journeys/' + page.params.id + '/share-preview', 'POST', options.value); createKey = mutationId(); } catch (e) { preview.value = null; error.value = errorText(e); } finally { busy.value = false; } }
async function create() {
  if (!preview.value || !acknowledge.value || busy.value) return; busy.value = true; error.value = '';
  try { const link = await api<ShareLink>('/journeys/' + page.params.id + '/shares', 'POST', { ...options.value, previewFingerprint: preview.value.fingerprint, acknowledge: true, clientMutationId: createKey }); lastLink.value = link; await refresh(); preview.value = null; acknowledge.value = false; createKey = mutationId(); message.value = '分享链接已创建。行程仍为私有，访客只能读取这份快照。'; }
  catch (e) { error.value = errorText(e); if (e instanceof ApiError && e.status === 409) { preview.value = null; acknowledge.value = false; } } finally { busy.value = false; }
}
async function revoke(link: ShareLink) { if (busy.value || !window.confirm('撤销这条分享链接？访客之后将无法通过它读取内容和照片。')) return; busy.value = true; error.value = ''; try { await api('/shares/' + link.id + '/revoke', 'POST', { clientMutationId: mutationId() }); await refresh(); if (lastLink.value?.id === link.id) lastLink.value = null; message.value = '分享链接已撤销。'; } catch (e) { error.value = errorText(e); } finally { busy.value = false; } }
function url(link: ShareLink) { return link.path ? location.origin + link.path : ''; }
async function copy(link: ShareLink) { try { await navigator.clipboard.writeText(url(link)); message.value = '链接已复制，持有完整链接的人可在有效期内查看。'; } catch { const input = document.getElementById('share-link-' + link.id) as HTMLInputElement | null; input?.focus(); input?.select(); message.value = '请复制已选中的完整链接，包含 # 后面的内容。'; } }
async function refreshLinks() { busy.value = true; error.value = ''; try { await refresh(); } catch (e) { error.value = errorText(e); } finally { busy.value = false; } }
onBeforeRouteLeave(() => !busy.value);
</script>
<template><section class="flow-view"><header class="flow-topbar"><button class="icon-button" aria-label="返回行程" :disabled="busy" @click="router.push('/journeys/' + page.params.id + (options.layer === 'actual' ? '/actual' : ''))"><AtlasIcon name="back"/></button><h2>分享这次旅程</h2><span class="icon-button"/></header><div class="flow-scroll share-editor"><p v-if="loading" role="status">正在读取可分享内容…</p><p v-if="error" class="flow-form-errors" role="alert">{{ error }}</p><p v-if="message" class="flow-save-state" role="status">{{ message }}</p><template v-if="!loading && journey"><h1 class="editor-title">选择想分享的部分</h1><p class="muted">先预览，再创建只读链接。默认有效 7 天，可随时撤销；编辑行程不会更新已创建的快照。</p><p v-if="choices && !choices.enabled" class="flow-form-errors">本机分享服务尚未配置，可以先预览范围。</p><fieldset class="share-fields" :disabled="busy"><div class="flow-field"><label for="share-title">分享标题</label><input id="share-title" v-model="options.title" maxlength="80"></div><div class="flow-field"><label for="share-layer">分享哪份安排</label><select id="share-layer" v-model="options.layer"><option value="plan">计划安排</option><option value="actual" :disabled="!journey.actualRouteId">实际记录</option></select></div><p class="small muted">默认分享目的地、每天的标题／地区、地点名称与交通。文字可能含住宿名称等个人信息，请在预览中检查。精确坐标、路径文件、到访记录和原图不在此范围。</p><label class="share-check"><input v-model="options.includeDates" type="checkbox">加入日期与时间</label><label class="share-check"><input v-model="options.includeNotes" type="checkbox">加入行程、地点备注与住宿字段</label><h3>选择要加入的日记</h3><p class="small muted">只列出本行程已写完的日记；未选中的日记保持私密，草稿不能分享。最多 20 篇。</p><label v-for="diary in choices?.diaries" :key="diary.id" class="share-check"><input v-model="options.diaryIds" type="checkbox" :value="diary.id" :disabled="!options.diaryIds.includes(diary.id) && options.diaryIds.length >= 20">{{ diary.title }}</label><p v-if="!choices?.diaries.length" class="muted">还没有可加入的已写完日记。</p><label class="share-check"><input v-model="options.includePhotos" type="checkbox">加入所选日记的照片与说明（仅预览图，最多 100 张）</label><div class="flow-field"><label for="share-expiry">链接有效期</label><select id="share-expiry" v-model="options.expiresInDays"><option :value="1">1 天</option><option :value="7">7 天</option><option :value="30">30 天</option></select></div><button class="secondary-button full" @click="showPreview">{{ busy ? '正在处理…' : '预览访客将看到的内容' }}</button></fieldset><section v-if="preview" class="share-preview"><h2>访客内容预览</h2><p class="small muted">{{ preview.snapshot.diaries.length }} 篇日记 · {{ preview.photoCount }} 张照片。下方即将作为快照保存；未勾选的字段不会加入。</p><SharedContent :snapshot="preview.snapshot" :photo-sources="photoSources"/><label class="share-check"><input v-model="acknowledge" type="checkbox" :disabled="busy">已检查预览，确认这些内容可供持有链接的人查看。</label><button class="primary full" :disabled="busy || !acknowledge || !choices?.enabled" @click="create">创建分享链接</button></section><section class="share-history"><div class="section-row"><h2>分享链接</h2><button class="text-button" :disabled="busy" @click="refreshLinks">刷新链接</button></div><p class="small muted">已撤销或过期的链接无法重新启用。已被访客保存的内容无法追回。</p><p v-if="!links.length" class="muted">还没有为此行程创建分享链接。</p><article v-for="link in links" :key="link.id" class="share-link-card"><h3>{{ link.title }}</h3><p>{{ link.state === 'active' ? '有效' : link.state === 'revoked' ? '已撤销' : '已过期' }} · {{ link.layer === 'plan' ? '计划安排' : '实际记录' }} · {{ link.diaryCount }} 篇日记 · {{ link.photoCount }} 张照片</p><p class="small muted">截止 {{ new Date(link.expiresAt).toLocaleString('zh-CN') }}</p><template v-if="link.path"><label class="visually-hidden" :for="'share-link-' + link.id">完整分享链接</label><input :id="'share-link-' + link.id" class="share-url" readonly :value="url(link)" @click="($event.target as HTMLInputElement).select()"><div class="share-actions"><button class="secondary-button" @click="copy(link)">复制链接</button><a class="text-button" :href="link.path" target="_blank" rel="noreferrer">打开访客页面</a><button class="text-button danger" :disabled="busy" @click="revoke(link)">撤销链接</button></div></template></article></section></template><button v-if="!loading && !journey" class="text-button" @click="load">重新读取</button></div></section></template>
